package org.apache.commons.math.stat;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.text.NumberFormat;
import java.util.*;
import java.util.Comparator;
import java.util.Iterator;
import java.util.TreeMap;
import org.apache.commons.math.MathRuntimeException;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

/**
 * Unit tests for org.apache.commons.math.stat.Frequency#getPct(Object)
 */
public class Frequency_getPct_TriageGen5Test {

    private static final double DELTA = 1e-10;

    @Test
    public void testGetPctWithInteger() {
        Frequency frequency = new Frequency();
        frequency.addValue(1);
        frequency.addValue(1);
        frequency.addValue(2);
        frequency.addValue(3);

        // Total count = 4. Count of 1 is 2. Pct = 2/4 = 0.5
        assertEquals(0.5, frequency.getPct(1), DELTA);
        // Count of 2 is 1. Pct = 1/4 = 0.25
        assertEquals(0.25, frequency.getPct(2), DELTA);
        // Count of 3 is 1. Pct = 1/4 = 0.25
        assertEquals(0.25, frequency.getPct(3), DELTA);
    }

    @Test
    public void testGetPctWithLong() {
        Frequency frequency = new Frequency();
        frequency.addValue(10L);
        frequency.addValue(20L);

        assertEquals(0.5, frequency.getPct(10L), DELTA);
    }

    @Test
    public void testGetPctWithString() {
        Frequency frequency = new Frequency();
        frequency.addValue("A");
        frequency.addValue("B");
        frequency.addValue("A");

        assertEquals(2.0 / 3.0, frequency.getPct("A"), DELTA);
    }

    @Test
    public void testGetPctWithNonExistentValue() {
        Frequency frequency = new Frequency();
        frequency.addValue(1);
        frequency.addValue(2);

        // Value not in frequency should return 0.0
        assertEquals(0.0, frequency.getPct(3), DELTA);
    }

    @Test
    public void testGetPctEmptyFrequency() {
        Frequency frequency = new Frequency();
        // Total count is 0. Division by zero in math usually results in NaN or 0 depending on implementation.
        // In Apache Commons Math, if count is 0, it returns 0.0 or NaN. 
        // Based on getCumPct logic, it usually returns 0.0 if total is 0.
        assertEquals(0.0, frequency.getPct(1), DELTA);
    }

    @Test(expected = ClassCastException.class)
    public void testGetPctWithNonComparable() {
        Frequency frequency = new Frequency();
        frequency.addValue(1);

        // Object that does not implement Comparable (e.g., a custom Object)
        // This will trigger the (Comparable<?>) cast in the deprecated method.
        Object nonComparable = new Object();
        frequency.getPct(nonComparable);
    }

    @Test
    public void testGetPctWithDouble() {
        Frequency frequency = new Frequency();
        frequency.addValue(1.5);
        frequency.addValue(2.5);
        frequency.addValue(1.5);

        assertEquals(2.0 / 3.0, frequency.getPct(1.5), DELTA);
    }
}
